-- Generated from station.csv, locker_location.csv, and locker_fee.csv.
-- Flyway supplies the transaction boundary for this migration.




DO $$
BEGIN
  IF (SELECT count(*) FROM station) < 114 THEN
    RAISE EXCEPTION 'Expected at least 114 stations, found %', (SELECT count(*) FROM station);
  END IF;
  IF (SELECT count(*) FROM locker_location) < 71 THEN
    RAISE EXCEPTION 'Expected at least 71 locker locations, found %', (SELECT count(*) FROM locker_location);
  END IF;
  IF (SELECT count(*) FROM locker_fee) < 315 THEN
    RAISE EXCEPTION 'Expected at least 315 locker fees, found %', (SELECT count(*) FROM locker_fee);
  END IF;
END $$;

SELECT count(*) AS station_count FROM station;
SELECT count(*) AS locker_location_count FROM locker_location;
SELECT count(*) AS locker_fee_count FROM locker_fee;
